let graphBindingTarget='';
function graphDefaultBinding(l,from=''){const expected=ProcessGraphCore.targetUnit(l),cut=ProcessGraphCore.isCut(l)&&ProcessGraphCore.unit(expected)==='м';return {from,metric:'area',mode:cut?'geometry':ProcessGraphCore.unit(expected)==='м²'?'direct':'context',factor:1,unit:expected,note:'',geometryBasis:l.scope==='batch'&&!l.operation?'batch':'unit',amount:null,parts:null};}
function graphBindingDescription(b,l){if(!b)return 'Материал не подключён';if(b.mode==='context')return 'Материал подключён · объём вручную';if(b.mode==='geometry')return (ProcessGraphCore.isCut(l)?'Длина реза: ':'Объём по геометрии: ')+dec(b.amount)+(b.geometryBasis==='parts'?' × '+dec(b.parts):'')+' '+b.unit+' · '+(b.geometryBasis==='batch'?'на партию':'на изделие');return ProcessGraphCore.METRICS[b.metric].name+' → '+b.unit+(b.mode==='norm'?' · норма '+dec(b.factor):' · напрямую');}
function graphBindingDialog(key,from){const l=graphLine(key);if(!l)return;graphBindingTarget=key;const expected=ProcessGraphCore.targetUnit(l),b={...graphDefaultBinding(l,from||''),...(l.processBinding||{})};if(from)b.from=from;const cut=ProcessGraphCore.isCut(l)&&ProcessGraphCore.unit(expected)==='м';modal('Материал и объём процесса',`<form onsubmit="graphSaveBinding(event,'${key}')"><h3>${esc(l.name)}</h3><p>Подключение передаёт характеристики материала. Объём работы задаётся отдельно выбранным способом.</p><div class="field"><label for="binding-from">Материал или предыдущий процесс</label><select id="binding-from" required><option value="">Выберите источник</option>${state.lines.filter(s=>s.processKey!==key).map(s=>`<option value="${s.processKey}" ${s.processKey===b.from?'selected':''}>${esc(s.name)} · ${esc(s.group)}</option>`).join('')}</select></div><div class="field"><label for="binding-mode">Как определять объём работы</label><select id="binding-mode" onchange="graphNormToggle()"><option value="context" ${b.mode==='context'?'selected':''}>Подключить материал · объём вводится вручную</option><option value="geometry" ${b.mode==='geometry'?'selected':''} ${!expected||l.pricingMode==='client'?'disabled':''}>${cut?'По длине контуров реза':'По заданной геометрии или количеству деталей'}</option><option value="direct" ${b.mode==='direct'?'selected':''} ${!expected||l.pricingMode==='client'?'disabled':''}>Из характеристики источника · одинаковые единицы</option><option value="norm" ${b.mode==='norm'?'selected':''} ${!expected||l.pricingMode==='client'?'disabled':''}>По подтверждённой норме пересчёта</option></select></div><div id="binding-auto"><div class="field"><label for="binding-metric">Характеристика из источника</label><select id="binding-metric" onchange="graphNormToggle()">${Object.entries(ProcessGraphCore.METRICS).map(([k,t])=>`<option value="${k}" ${k===b.metric?'selected':''}>${esc(t.name)} · ${esc(MaterialCore.unitLabel(t.unit))}</option>`).join('')}</select></div><div class="field" id="binding-factor-field"><label for="binding-factor">Норма: ${esc(expected)} на единицу выбранной характеристики</label><input id="binding-factor" type="number" min="0" step="any" value="${b.mode==='norm'?b.factor:''}"></div></div><div id="binding-geometry"><div class="field"><label for="binding-amount">${cut?'Длина контуров реза, м':'Объём работы, '+esc(expected)}</label><input id="binding-amount" type="number" min="0" step="any" value="${b.amount??''}"></div><div class="field"><label for="binding-basis">К чему относится этот объём</label><select id="binding-basis" onchange="graphNormToggle()"><option value="unit" ${b.geometryBasis==='unit'?'selected':''}>Суммарно на одно изделие</option><option value="batch" ${b.geometryBasis==='batch'?'selected':''}>Суммарно на всю партию</option><option value="parts" ${b.geometryBasis==='parts'?'selected':''}>На одну деталь × число деталей в изделии</option></select></div><div class="field" id="binding-parts-field"><label for="binding-parts">Количество деталей на одно изделие</label><input id="binding-parts" type="number" min="0" step="1" value="${b.parts??''}"></div><p class="small">${cut?'Учитывайте внешний контур и внутренние вырезы. Длина и площадь закупленного листа не равны длине реза.':'Укажите измеренный объём; он не выводится из площади без нормы.'}</p></div><div class="field"><label for="binding-note">Основание объёма / нормы</label><input id="binding-note" value="${esc(b.note)}" placeholder="Чертёж, длина контуров, согласованная норма…"></div><p id="binding-help" class="note info" aria-live="polite"></p><p id="graph-error" role="alert"></p><button class="primary">Сохранить связь</button></form>`);graphNormToggle();}
function graphNormToggle(){const mode=$('binding-mode').value,metric=$('binding-metric').value,l=graphLine($('binding-from').value);$('binding-auto').hidden=!['direct','norm'].includes(mode);$('binding-factor-field').hidden=mode!=='norm';$('binding-geometry').hidden=mode!=='geometry';$('binding-parts-field').hidden=$('binding-basis').value!=='parts';const target=graphLine(graphBindingTarget),expected=target?ProcessGraphCore.targetUnit(target):'';const compatible=ProcessGraphCore.unit(ProcessGraphCore.METRICS[metric]?.unit)===ProcessGraphCore.unit(expected);$('binding-help').textContent=mode==='context'?'Связь сохранится без пересчёта единиц. Объём, часы или минуты можно задать в редакторе позиции.':mode==='geometry'?'Пустой объём допустим для сохранения связи: калькуляция останется неполной до его заполнения. После раскроя отдельно укажите характеристики готовых деталей.':mode==='direct'&&!compatible?'Эта характеристика не совпадает с единицей ставки. Выберите геометрию, ручной объём или подтверждённую норму. Площадь нельзя подставить вместо длины реза.':'Используются характеристики подключённого источника. После раскроя — только заданная геометрия готовых деталей.';}
function graphSaveBinding(e,key){e.preventDefault();const l=graphLine(key),mode=$('binding-mode').value,b={from:$('binding-from').value,metric:$('binding-metric').value,mode,factor:mode==='norm'?($('binding-factor').value===''?null:Number($('binding-factor').value)):1,unit:ProcessGraphCore.targetUnit(l),note:$('binding-note').value.trim()};if(mode==='geometry')Object.assign(b,{geometryBasis:$('binding-basis').value,amount:$('binding-amount').value===''?null:Number($('binding-amount').value),parts:$('binding-parts').value===''?null:Number($('binding-parts').value)});try{if(!b.from)throw Error('Выберите источник');if(mode==='norm'&&!b.note)throw Error('Укажите основание нормы');if(mode==='direct'&&ProcessGraphCore.unit(ProcessGraphCore.METRICS[b.metric].unit)!==ProcessGraphCore.unit(b.unit))throw Error('Выберите геометрию, ручной объём или норму: единицы различаются');const lines=state.lines.map(x=>x===l?{...x,processBinding:b}:x);ProcessGraphCore.validate(lines);l.processBinding=b;l.confirmed=false;graphConnectFrom='';graphSelected=key;persist();$('modal').close();render();const issue=ProcessGraphCore.resolve(state).errors.find(x=>x.startsWith(l.name+':'));if(issue)toast('Связь сохранена. Уточните объём или характеристики.');}catch(e){$('graph-error').textContent=e.message;}}
function graphOutputDialog(key){const l=graphLine(key);if(!l)return;const o=l.processOutput||{basis:'unit',source:''};modal('Готовые детали после процесса',`<form onsubmit="graphSaveOutput(event,'${key}')"><h3>${esc(l.name)}</h3><p>Суммарные характеристики <b>всех готовых деталей</b>, а не закупленной заготовки. Неизвестные значения оставьте пустыми. Площадь здесь не умножается на количество деталей повторно.</p><div class="field"><label for="output-basis">Характеристики относятся</label><select id="output-basis"><option value="unit" ${o.basis==='unit'?'selected':''}>К одному изделию</option><option value="batch" ${o.basis==='batch'?'selected':''}>Ко всей партии</option></select></div><div class="grid2">${Object.entries(ProcessGraphCore.METRICS).map(([k,t])=>`<div class="field"><label for="output-${k}">${esc(t.name)}, ${esc(MaterialCore.unitLabel(t.unit))}</label><input id="output-${k}" type="number" min="0" step="any" value="${o[k]??''}"></div>`).join('')}</div><div class="field"><label for="output-source">Основание характеристик готовых деталей</label><input id="output-source" value="${esc(o.source)}" required></div><label class="checkrow"><input id="output-confirm" type="checkbox" required>Проверены количество деталей и фактические поверхности обработки</label><p class="small">Эти данные передаются шлифовке и покрытию по исходящим связям. Отходы и площадь оставшейся части листа в них не входят.</p><p id="graph-error" role="alert"></p><button class="primary">Сохранить готовые детали</button></form>`);}
function graphSaveOutput(e,key){e.preventDefault();const l=graphLine(key),o={basis:$('output-basis').value,source:$('output-source').value.trim()};if(!$('output-confirm').checked||!o.source)return;for(const k of Object.keys(ProcessGraphCore.METRICS))o[k]=$('output-'+k).value===''?null:Number($('output-'+k).value);try{ProcessGraphCore.validate(state.lines.map(x=>x===l?{...l,processOutput:o}:x));l.processOutput=o;l.confirmed=false;persist();$('modal').close();render();}catch(e){$('graph-error').textContent=e.message;}}
function graphRecommendationsHTML(l,form=false){const rules=ProcessRecommendationsCore.rules(l,state.lines,CATALOG);if(!rules.length)return '';const prefix=(form?'form':'node')+'-recommend-'+l.id;return `<details class="graph-recommendations" ${form?'':'open'}><summary>Рекомендуемые следующие процессы</summary><p class="small">Добавление создаёт связь с выбранным материалом${l.kind==='work'?' / готовыми деталями':''}. Применимые операции выбирайте по проекту; нормы и объёмы не подставляются по догадке.</p>${rules.map((r,i)=>`<div class="field"><label for="${prefix}-${i}">${esc(r.label)}</label><select id="${prefix}-${i}">${r.options.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${money(c.price)} / ${esc(MaterialCore.unitLabel(c.unit))}${ProcessRecommendationsCore.linked(state.lines,l,c)?' · уже связано':''}</option>`).join('')}</select><button type="button" onclick="graphAddRecommendation('${l.id}',${i},${form})">${form?'Сохранить материал и добавить':'Добавить и связать'}</button></div>`).join('')}<p class="small">Не добавляйте отдельную обработку, если она уже включена в комплексную работу.</p></details>`;}
function graphAddRecommendation(id,index,form=false){let source=state.lines.find(l=>l.id===id);if(!source)return;const rules=ProcessRecommendationsCore.rules(source,state.lines,CATALOG),rule=rules[index],prefix=(form?'form':'node')+'-recommend-'+id,candidate=rule?.options.find(c=>c.id===$(prefix+'-'+index).value);if(!candidate)return;if(form){commitLine({preventDefault(){}},id);if($('modal').open)return;source=state.lines.find(l=>l.id===id);}graphEnsureKeys();const existing=ProcessRecommendationsCore.linked(state.lines,source,candidate);if(existing){graphSelected=existing.processKey;page=20;render();toast('Этот процесс уже связан с материалом');return;}const l=lineFrom(rule.custom?undefined:candidate);Object.assign(l,{processKey:uid(),catalogId:candidate.id,name:candidate.name,kind:candidate.kind,unit:candidate.unit,price:candidate.price??null,qty:null,group:source.group,scope:source.scope,confirmed:false});if(rule.custom)l.source='Ручная ставка: отдельная ставка отсутствует';l.processBinding=graphDefaultBinding(l,source.processKey);const p=graphLayout().get(source.processKey)||{x:40,y:55},siblings=state.lines.filter(x=>x.processBinding?.from===source.processKey).length;l.processPosition={x:Math.min(20000,p.x+330),y:Math.min(20000,p.y+siblings*320)};state.lines.push(l);state.version=3;state.schemaVersion=3;graphSelected=l.processKey;page=20;persist();render();graphBindingDialog(l.processKey);}
(function(){const previousEdit=editLine;editLine=function(id){previousEdit(id);const l=state.lines.find(l=>l.id===id);if(l?.kind==='material'&&$('lineForm'))$('lineForm').insertAdjacentHTML('afterbegin',graphRecommendationsHTML(l,true));};})();
